head.script:
///////// 1. 변수 및 선언 영역 /////////
scwin.vBzProcsNo = "";
scwin.pBzProcsNo = "";
scwin.visuShrsLabelNm = "주식";
scwin.vIsuDtlRowPosition = "";
scwin.chkPrtdepoCond = true;
scwin.formCd = "";
scwin.vStkOptComNm = "";
scwin.cal = true;
/************************************************************************************
 * ID           :	ULDSTF92002
 * File           :	ULDSTF92002.xml
 * Name         :	주권 주식발행관리(추가상장)
 * Author       :	yoo
 * Description  :	주권 주식발행관리(추가상장)
 * Create Date  :	2026-07-31
 ************************************************************************************/

// 유가보호예수땜시추가
// 스톡옵션 의무보유땜시 추가
scwin.market = $c.session.getUserInfo("market");
scwin.BTN_MAP = {
    "save" : "btn_Save",       // [저장]
    "modify" : "btn_Update",      // [수정]
    "delete" : "btn_Delete",     // [삭제]
};

///////// 2. 초기화 영역 /////////
/**
 * @method
 * @name onpageload
 * @description 화면 로딩 시 초기 처리 — init 호출
 * @returns {void}
 * @hidden N
 */
scwin.onpageload = async function () {
    try {
        await scwin.init();
    } catch (ex) {
        $c.exception.handleError(ex, { context : "ULDSTF92002.onpageload" });
    }
};

/**
 * @method
 * @name init
 * @description 화면 초기화 — 조회조건·상태값 기본 설정.
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.init = async function () {
    scwin.vBzProcsNo = $c.win.getParent().scwin.clickBzProcsNo;
    scwin.vSecugrpID = $c.win.getParent().scwin.fr_SecuGrpId
    scwin.vPageTYp = $c.win.getParent().scwin.vPageTYp;
    scwin.vSPOT_ISU_TRD_MKT_TP_CD = $c.win.getParent().scwin.vSPOT_ISU_TRD_MKT_TP_CD;

    txb_isurCd.setValue($c.win.getParent().ibx_isurCd.getValue());
    ibx_COM_NM.setValue($c.win.getParent().ibx_comNm.getValue());
    sbx_STKCERT_KIND_CD.setSelectedIndex(-1);

    scwin.gAcptNo = $c.win.getParent().scwin.gAcptNo;
    scwin.gAcptSeq = ($c.win.getParent().scwin.gAcptSeq === "" ? 0 : $c.win.getParent().scwin.gAcptSeq);

    // 상장수수료를 위한 접수번호
    scwin.gAcptNoListFee = $c.win.getParent().scwin.gAcptNoListFee;

    await scwin.setObjectState();

    // resizeToWin() ;
    await scwin.searchCode();
    await scwin.setComboCode();

    scwin.setPanelPREFSTK(false); // 일단 false;
    scwin.setPREFSTKItem(false); // 일단 false;

    ica_APPROV_DD.setValue($c.date.getServerDateTime());
    if (scwin.vBzProcsNo !== "") {
        dlt_listMethdTpCd.setJSON([{ value: '1', text: '신주상장' }, { value: '2', text: '추가상장' }, { value: '3', text: '변경상장' }, { value: '4', text: '신규상장' }, { value: '5', text: '재상장' }]);
        ibx_LIST_METHD_TP_CD.setNodeSet("data:dlt_listMethdTpCd", "text", "value");
        await scwin.readSync();
    } else {

        if (scwin.gAcptNo !== undefined && scwin.gAcptNo !== "") {
            await scwin.extrReadSync();
            // scwin.fn_SetHeader('N');
        } else {
            // scwin.fn_SetHeader('Y');
        }

        if (scwin.vPageTYp === '1') {
            dlt_listMethdTpCd.setJSON([{ value: '2', text: '추가상장' }]);
            ibx_LIST_METHD_TP_CD.setNodeSet("data:dlt_listMethdTpCd", "text", "value");
            ibx_LIST_METHD_TP_CD.setSelectedIndex(0);
            await scwin.nprefstkReadSync(ibx_ISU_CD.getValue());
        } else if (scwin.vPageTYp === '2') {
            dlt_listMethdTpCd.setJSON([{ value: '3', text: '변경상장' }]);
            ibx_LIST_METHD_TP_CD.setNodeSet("data:dlt_listMethdTpCd", "text", "value");
            ibx_LIST_METHD_TP_CD.setSelectedIndex(0);
        }
    }

    scwin.setTabPanel();

    let arrBtn = [];
    arrBtn.push(btn_Save);
    arrBtn.push(btn_Update);
    arrBtn.push(btn_Delete);

    if (sbx_STKCERT_KIND_CD.getValue() !== "KDR" && sbx_STKCERT_KIND_CD.getValue().substring(0, 1) === "K") {
        scwin.setNPARVALSTK(true);
    } else {
        scwin.setNPARVALSTK(false);
    }
    // 주식발행사유가 스톡옵션행사(117)(유), 주식매수선택권행사(614)(코) 인경우 주식매수선택권 의무보유 관리 팝업창 호출
    let parentSrc = $c.win.getParent().scwin.vScrenID;
    if ((parentSrc === "ULDSTF05200.xml" || parentSrc === "ULDSTF05255.xml") && (scwin.vSecugrpID.indexOf($c.lc.glb.SECUGRP_ID_ST) > -1 || scwin.vSecugrpID.indexOf($c.lc.glb.SECUGRP_ID_DR) > -1 || scwin.vSecugrpID.indexOf($c.lc.glb.SECUGRP_ID_FS) > -1) &&
        (sbx_STK_ISU_RSN_CD.getValue() === "117" || sbx_STK_ISU_RSN_CD.getValue() === "614")) {
        scwin.vStkOptIsurCd = txb_isurCd.getValue();
        scwin.vStkOptComNm = ibx_COM_NM.getValue();
        // await $c.win.openPopup 함수로 전환 필요 : await $c.frame.CreateDialogFrame("ULDSTF40003", "/lstmgt/ULDSTF40003.gfm", "주식매수선택권 의무보유 관리", 100, 100, 1300, 790, "window");

        const opts = {
            id: "ULDSTF40003",
            popupName: "주식매수선택권 의무보유 관리",
            width: 900,
            height: 1000,
            frameModal: "top",
            type: "pageFramePopup",
        };
        const res = await $c.win.openPopup("/ui/lst/lstmgt/ULDSTF40003.xml", opts);
    }
};

///////// 3. 컴포넌트 이벤트 영역 /////////
/**
 * @method
 * @name save
 * @description 입력값을 저장한다.
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.save = async function () {
    try {
        scwin.TR_JOB = 'I';
        if (scwin.checkForm()) {
            if (! await $c.lc.isProcess(scwin.TR_JOB)) return;
            scwin.vBzProcsNo = await $c.stf.getNewBzProcNo();
            if (scwin.vBzProcsNo.length !== 14) {
                $c.win.alert($c.stf.getMessageParam("MSG-0010", ""));
            } else {
                dma_Isu.set("bzProcsNo", scwin.vBzProcsNo);

                if ((scwin.market === '1') &&
                    scwin.chkPrtdepoCond00() && scwin.chkPrtdepoCond01()) {

                    if (scwin.chkPrtdepoCond) {
                        scwin.prtdepoReadSyncSTKCount();
                    }
                }
                if ((scwin.market === '1') &&
                    scwin.chkPrtdepoCond00() && scwin.chkPrtdepoCond01() && scwin.chkPrtdepoCond02() &&
                    (scwin.gPrtdepoCount > 0) &&
                    scwin.chkPrtdepoCond) {
                    $c.win.alert("               【의무보유 시장조치 안내】\n해당 종목에 의무보유중인 증권이 있습니다.\n의무보유내역에서 의무보유수량을 정정조치하여 주시기 바랍니다.");
                    scwin.prtdepoReadSyncSTK();
                    scwin.chkPrtdepoCond = false;
                    scwin.formCd = "68155";
                    return;
                }
                if ((scwin.market === '1') &&
                    scwin.chkPrtdepoCond00() && scwin.chkPrtdepoCond03()) {
                    let msg = "변경상장사유가 의무보유정보 수정대상이나 수정조치가 이루어지지 않았습니다.\n다시 한번 수정여부를 확인하여 주십시오.\n수정없이 그대로 진행하기를 원하시면 확인을 누르십시오.";
                    let res = window.confirm(msg);
                    if (!res) {
                        return;
                    }
                }
                await scwin.trs($c.lc.glb.TRS_IDX_INSERT);
            }
        }
    } catch (ex) {
        await $c.exception.handleError(ex, { context : "ULDSTF92002.save" });
    }
};

/**
 * @method
 * @name update
 * @description 입력값을 수정 저장한다.
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.update = async function () {
    try {
        scwin.TR_JOB = 'U';
        if (scwin.checkForm()) {
            if (! await $c.lc.isProcess(scwin.TR_JOB)) return;
            scwin.trs($c.lc.glb.TRS_IDX_UPDATE);
        }
    } catch (ex) {
        await $c.exception.handleError(ex, { context : "ULDSTF92002.update" });
    }
};

/**
 * @method
 * @name delete
 * @description 선택 자료를 삭제한다.
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.delete = async function () {
    try {
        scwin.TR_JOB = 'D';
        if (! await $c.lc.isProcess(scwin.TR_JOB)) return;
        if (! await $c.lc.checkDeleteDiscls(dma_DELETE, dma_Isu.get("bzProcsNo"))) return;
        await scwin.trs($c.lc.glb.TRS_IDX_DELETE);
    } catch (ex) {
        await $c.exception.handleError(ex, { context : "ULDSTF92002.delete" });
    }
};

