/**
 * @method
 * @name chk_PREFSTK_TP_CD_onclick
 * @description chk_PREFSTK_TP_CD 클릭 이벤트
 * @param {Object} info 이벤트 정보 객체
 * @returns {void}
 * @hidden N
 */
scwin.chk_PREFSTK_TP_CD_onclick = function (info) {
    try {
        if (info.newValue === "Y") {
            scwin.setPanelPREFSTK(true);
        } else {
            scwin.setPanelPREFSTK(false);
        }
        grp_Item.focus();
    } catch (ex) {
        $c.exception.handleError(ex, { context : "ULDSTF92002.chk_PREFSTK_TP_CD_onclick" });
    }
};

