 * @hidden N
 */
scwin.img_ISU_ENG_SYMBL_onclick = function () {
    try {
        if (ibx_ISU_ENG_SYMBL.getValue() === "") {
            $c.win.alert("[영문종목심볼]을 입력하세요.");
            ibx_ISU_ENG_SYMBL.focus();
            return false;
        } else {
            if ($c.lc.engSymblCheck(ibx_ISU_ENG_SYMBL.getValue())) {
                $c.lc.chkCorpSymblDoubleInput(ibx_ISU_ENG_SYMBL.getValue(), txb_isurCd.getValue(), dts_Symbl);
                if (!$c.util.isEmpty(MSG_SYMBL_DOUBLE_INPUT)) {
                    $c.win.alert(MSG_SYMBL_DOUBLE_INPUT);
                }
            } else {
                ibx_ISU_ENG_SYMBL.focus();
                return false;
            }
        }
    } catch (ex) {
        $c.exception.handleError(ex, { context : "ULDSTF92002.img_ISU_ENG_SYMBL_onclick" });
    }
};

