/**
 * @method
 * @name sbx_STK_ISU_RSN_CD_onselchange
 * @description sbx_STK_ISU_RSN_CD 선택 변경 이벤트
 * @returns {void}
 * @hidden N
 */
scwin.sbx_STK_ISU_RSN_CD_onselchange = function () {
    try {
        if (!btn_RecvIsuDel.getDisabled()) {
            if (scwin.market === '1' && scwin.vPageTYp === "2" && ibx_LIST_METHD_TP_CD.getValue() === $c.lc.glb.LIST_METHD_TP_CD_3) {
                // 유가, 변경상장
                if (sbx_STK_ISU_RSN_CD.getValue() !== "" &&
                    sbx_STK_ISU_RSN_CD.getValue() !== "170" &&
                    sbx_STK_ISU_RSN_CD.getValue() !== "171" &&
                    sbx_STK_ISU_RSN_CD.getValue() !== "172" &&
                    sbx_STK_ISU_RSN_CD.getValue() !== "173" &&
                    sbx_STK_ISU_RSN_CD.getValue() !== "174" &&
                    sbx_STK_ISU_RSN_CD.getValue() !== "177" &&
                    sbx_STK_ISU_RSN_CD.getValue() !== "118" &&
                    sbx_STK_ISU_RSN_CD.getValue() !== "160" &&
                    sbx_STK_ISU_RSN_CD.getValue() !== "161" &&
                    sbx_STK_ISU_RSN_CD.getValue() !== "180" &&
                    sbx_STK_ISU_RSN_CD.getValue() !== "162" &&
                    sbx_STK_ISU_RSN_CD.getValue() !== "163" &&
                    sbx_STK_ISU_RSN_CD.getValue() !== "175" &&
                    sbx_STK_ISU_RSN_CD.getValue() !== "176") {
                    // confirm: 반환값을 동기 boolean 으로 소비하는 위치 — $c.win.confirm 은 Promise 라 1:1 치환 불가(컨벤션 예외, 전환 시 async 재설계 필요)
                    if (!confirm("변경상장에서 안내문 형식이 정의되지 않은 주식 발행사유 입니다. \n그래도 선택한 주식발행사유를 입력하시겠습니까?")) {
                        sbx_STK_ISU_RSN_CD.setValue('');
                        return;
                    }
                }
            }
        }
        // scwin.setTabPanel(); //625:우선주의 보통주전환  추가(2017.07.14)

        scwin.calcuAccIsuShrs();
        scwin.calcuAccIsuCap();
    } catch (ex) {
        $c.exception.handleError(ex, { context : "ULDSTF92002.sbx_STK_ISU_RSN_CD_onselchange" });
    }
};

