/**
 * @method
 * @name button_1_onclick
 * @description 「종류주식」 버튼 클릭
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.button_1_onclick = async function () {
    try {
        let reqMap = {
            isurCd: txb_isurCd.getValue(),
            stkcertKindCd: sbx_STKCERT_KIND_CD.getValue()
        };
        const sbmOptions = {
            id: "sbm_select_acptno",
            action: "/api/listing/lstproc/stock/chglisting/select-apfm-by-acptno",
            method: "get",
            target: "dma_KindStkBzProcsNo=body",
            isProcessMsg: true
        };
        const res = await $c.sbm.executeDynamic(sbmOptions, reqMap);

        if (res.responseJSON.success) {
            scwin.pBzProcsNo = dma_KindStkBzProcsNo.get("bzProcsNo");

            let url = "/ui/lstproc/ULDSTF05106_read.xml";
            let popTitle = $c.lc.getSecuGrpNm(scwin.vSecugrpID) + " 종류주식 상세";

            const opts = {
                id: "ULDSTF05106_read",
                popupName: popTitle,
                width: 1135,
                height: 840,
                frameModal: "top",
            };

            await $c.win.openPopup(url, opts);
        }
    } catch (ex) {
        await $c.exception.handleError(ex, { context : "ULDSTF92002.button_1_onclick" });
    }
};

