            frameModal: "top",
        };

        let result = await $c.win.openPopup("/ui/lst/common/ULDSTF92026.xml", opts, { "reqJson" : dlt_IsuDtl.getRowJSON(rowIndex) });

        dlt_IsuDtl.setCellData(rowIndex, "ksdStockIssuYn", result);
    } catch (ex) {
        await $c.exception.handleError(ex, { context : "ULDSTF92002.grd_IsuDtl_oncelldblclick" });
    }
};

/**
 * @method
 * @name ibx_LIST_METHD_TP_CD_onviewchange
 * @description ibx_LIST_METHD_TP_CD 값 변경 이벤트
 * @param {Object} info 이벤트 정보 객체
 * @returns {void}
 * @hidden N
 */
scwin.ibx_LIST_METHD_TP_CD_onviewchange = function (info) {
    try {
        if (ibx_LIST_METHD_TP_CD.getValue() === $c.lc.glb.LIST_METHD_TP_CD_1) {
            let vListMthTpCd = ibx_LIST_METHD_TP_CD.getValue();
            if (scwin.vPageTYp === '1') {
                if (vListMthTpCd !== $c.lc.glb.LIST_METHD_TP_CD_2) {
                    $c.win.alert("이화면에서는  상장방식을 [추가상장]만 선택할 수 있습니다.");
                    ibx_LIST_METHD_TP_CD.setValue($c.lc.glb.LIST_METHD_TP_CD_2);
                    ibx_LIST_METHD_TP_CD.focus();
                    return false;
                }
            } else if (scwin.vPageTYp === '2') {
                if (vListMthTpCd !== $c.lc.glb.LIST_METHD_TP_CD_3) {
                    $c.win.alert("이화면에서는  상장방식을 [변경상장]만 선택할 수 있습니다.");
                    ibx_LIST_METHD_TP_CD.setValue($c.lc.glb.LIST_METHD_TP_CD_3);
                    ibx_LIST_METHD_TP_CD.focus();
                    return false;
                }
            }
        }
    } catch (ex) {
        $c.exception.handleError(ex, { context : "ULDSTF92002.ibx_LIST_METHD_TP_CD_onviewchange" });
    }
};

/**
 * @method
