/**
 * @method
 * @name nprefstkReadSync
 * @description 신형우선주(NPREFSTK) 정보를 조회한다.
 * @param {*} isucd isucd
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.nprefstkReadSync = async function (isucd) {

    let reqMap = {
        // 종목코드
        isuCd: isucd
    };
    const sbmOptions = {
        id: "sbm_select",
        action: "/api/listing/lstproc/stock/issuance-manage-new-prestk/select-one",
        method: "get",
        target: "dma_NEWPREFSTK=body",
        isProcessMsg: true
    };
    const res = await $c.sbm.executeDynamic(sbmOptions, reqMap);
    if (res.responseJSON.success) {
        if (res.responseJSON.body !== null) {
            dma_Isu.set("prefstkIsuDd", dma_NEWPREFSTK.get("isuDd"));
            dma_Isu.set("prefstkDivRt", dma_NEWPREFSTK.get("prefstkDivRt"));
            dma_Isu.set("prefstkContinDeadlineYys", dma_NEWPREFSTK.get("prefstkContinDeadlineYys"));
            dma_Isu.set("prefstkContinDeadlineMm", dma_NEWPREFSTK.get("prefstkContinDeadlineMm"));
            dma_Isu.set("prefstkContinDeadlineDys", dma_NEWPREFSTK.get("prefstkContinDeadlineDys"));
            dma_Isu.set("prefstkEndDd", dma_NEWPREFSTK.get("prefstkEndDd"));
            scwin.setNprefCheckBox(dma_NEWPREFSTK);
            dma_Isu.set("newprefstkRemk", dma_NEWPREFSTK.get("newprefstkRemk"));
            chk_PREFSTK_TP_CD.setValue(1);
            scwin.setPREFSTKItem(true);
            scwin.setPanelPREFSTK(true);
        } else {
            dma_Isu.set("prefstkIsuDd", '');
            dma_Isu.set("prefstkDivRt", '');
            dma_Isu.set("prefstkContinDeadlineYys", '');
            dma_Isu.set("prefstkContinDeadlineMm", '');
            dma_Isu.set("prefstkContinDeadlineDys", '');
            dma_Isu.set("prefstkEndDd", '');
            dma_Isu.set("indefinpdYn", '');
            dma_Isu.set("partctpYn", '');
            dma_Isu.set("acctpYn", '');
            dma_Isu.set("ndivtmVoterghtYn", '');
            dma_Isu.set("newprefstkRemk", '');
            chk_PREFSTK_TP_CD.setValue(0);
            scwin.setPanelPREFSTK(false);
            scwin.setPREFSTKEvent();
        }
    }
};

/**
 * @method
 * @name extrReadSync
 * @description 추가 발행 정보를 조회한다.
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.extrReadSync = async function () {

    let reqMap = {
        acptNo: scwin.gAcptNo,
        byacptnoSeq: scwin.gAcptSeq
    };
    const sbmOptions = {
        id: "sbm_select",
        action: "/api/listing/lstproc/stock/issuance-manage-dtl/select-list",
        method: "get",
        target: "dma_Isu=body.acptInfo, dlt_IsuDtl=body.isuDtlInfo,dlt_PRTDEPO=body.prtdepoInfo,dma_DoubleChk=body.dblChkCnt",
        isProcessMsg: true
    };
    const res = await $c.sbm.executeDynamic(sbmOptions, reqMap);

    if (res.responseJSON.success) {
        if (dma_Isu.get("nparvalstkYn") === 'Y') {
            chk_NPARVALSTK_YN.setValue(1);
        }
        scwin.setNPARVALSTKYNEvent();
        let modDocCnt = dma_DoubleChk.get("cnt");
        if (modDocCnt > 0) {
            $c.win.alert("◆  처리방법 안내  ◆\n\r\n\r" + "선택내용은 [정정]신청건으로 이전신청서가 처리되어 주식발행내역에 존재합니다.\n\r\n\r" + "상장주식수와 상장자본금이 중복계산되오니 다음의 방법으로 처리바랍니다.\n\r\n\r\n\r" + "case 1. 이전신청서가 공시가 됐을경우 \n\r\n\r" + "     정정신청건 삭제([신청종목삭제] 버튼) -> 주식발행내역에서 이전처리건을 선택하여 정정내용을 수정 -> 정정공시문 작성 \n\r\n\r\n\r" + "caer 2. 이전신청서가 미공시  됐을경우 \n\r\n\r" + "     주식발행내역에서 이전처리건을 선택하여 삭제 -> 정정신청건 저장 -> 공시문 작성\n\r");
        }

        let vCurDate = $c.date.getServerDateTime();
        if (scwin.vBzProcsNo === "") {
            $c.util.setButtonState("grp_btnBox", "insert", scwin.BTN_MAP);

            scwin.initForm('C');
        } else {
            scwin.initForm('X');
            if (vCurDate <= ibx_LIST_DD.getValue()) {
                $c.util.setButtonState("grp_btnBox", "update", scwin.BTN_MAP);
            } else {
                if (dma_Isu.get("disclsYn") === 'Y') {
                    $c.util.setButtonState("grp_btnBox", "error", scwin.BTN_MAP);
                } else {
                    $c.util.setButtonState("grp_btnBox", "update", scwin.BTN_MAP);
                }
            }
        }
        if (scwin.gAcptNo !== "" && scwin.vBzProcsNo === "") {
            btn_RecvIsuDel.setDisabled(false);
        } else {
            btn_RecvIsuDel.setDisabled(true);
        }
        if (scwin.gAcptNo !== "" && scwin.vBzProcsNo === "") {
            let vListMthTpCd = dma_Isu.get("listMethdTpCd");
            if (vListMthTpCd === 1 || vListMthTpCd === 2) {
                // 주식발행사유로 체크하지말고 건수로 하자..
                if (dlt_IsuDtl.getRowCount() === 0) {
                    dlt_IsuDtl.insertRow();
                    dlt_IsuDtl.setCellData(0, "isuRnd", dma_Isu.get("isuRnd"));
                    dlt_IsuDtl.setCellData(0, "isuPrc", dma_Isu.get("isuPrc"));
                    dlt_IsuDtl.setCellData(0, "isuShrs", dma_Isu.get("isuShrs"));
                    dlt_IsuDtl.setCellData(0, "isuDd", dma_Isu.get("isuDd"));
                    dlt_IsuDtl.setCellData(0, "per1strCap", dma_Isu.get("per1strCap"));
                } else {
                    dlt_IsuDtl.setBroadcast(false);
                    for (j = 0; j <= dlt_IsuDtl.getRowCount(); j++) {
                        dlt_IsuDtl.setCellData(j, "isuRnd", dma_Isu.get("isuRnd"));
                    }
                    dlt_IsuDtl.setBroadcast(true, true);
                }
            }
        }
    }
};

/**
 * @method
 * @name readSync
 * @description 상세조회
