        txb_CURR_ISO_NM_1.setValue("(" + dma_Isu.get("currIsoCd") + ")");
        txb_CURR_ISO_NM_2.setValue("(" + dma_Isu.get("currIsoCd") + ")");
        txb_CURR_ISO_NM_3.setValue("(" + dma_Isu.get("currIsoCd") + ")");
        txb_CURR_ISO_NM_4.setValue("(" + dma_Isu.get("currIsoCd") + ")");
        scwin.setNprefCheckBox(dma_Isu);
        // scwin.setCheckboxData(chk_NEWSTK_REL_LAWST_YN, dma_Isu.get("newstkRelLawstYn"));
        scwin.setCheckboxData(chk_BACKLIST_YN, dma_Isu.get("backlistYn"));

        await scwin.prtdepoReadSync();

        let vCurDate = $c.date.getServerDateTime();
        if (scwin.vBzProcsNo === "") {
            $c.util.setButtonState("grp_btnBox", "insert", scwin.BTN_MAP);
            scwin.initForm('C');
        } else {
            scwin.initForm('X');
            if (vCurDate <= ibx_LIST_DD.getValue()) {
                $c.util.setButtonState("grp_btnBox", "update", scwin.BTN_MAP);
            } else {
                if (dma_Isu.get("disclsYn") === 'Y') {
                    $c.util.setButtonState("grp_btnBox", "error", scwin.BTN_MAP);
                } else {
                    $c.util.setButtonState("grp_btnBox", "update", scwin.BTN_MAP);
                }
            }
        }
        if (scwin.gAcptNo !== "" && scwin.vBzProcsNo === "") {
            btn_RecvIsuDel.setDisabled(false);
        } else {
            btn_RecvIsuDel.setDisabled(true);
        }
        if (scwin.gAcptNo !== "" && scwin.vBzProcsNo === "") {
            let vListMthTpCd = dma_Isu.get("listMethdTpCd");
            if (vListMthTpCd === 1 || vListMthTpCd === 2) {
                // 주식발행사유로 체크하지말고 건수로 하자..
                if (dlt_IsuDtl.getRowCount() === 0) {
                    dlt_IsuDtl.insertRow();
                    dlt_IsuDtl.setCellData(0, "isuRnd", dma_Isu.get("isuRnd"));
                    dlt_IsuDtl.setCellData(0, "isuPrc", dma_Isu.get("isuPrc"));
                    dlt_IsuDtl.setCellData(0, "isuShrs", dma_Isu.get("isuShrs"));
                    dlt_IsuDtl.setCellData(0, "isuDd", dma_Isu.get("isuDd"));
                    dlt_IsuDtl.setCellData(0, "per1strCap", dma_Isu.get("per1strCap"));
                } else {
                    dlt_IsuDtl.setBroadcast(false);
                    for (j = 1; j <= dlt_IsuDtl.getRowCount(); j++) {
                        dlt_IsuDtl.setCellData(j, "isuRnd", dma_Isu.get("isuRnd"));
                    }
                    dlt_IsuDtl.setBroadcast(true, true);
                }
            }
        }

        scwin.ibx_LIST_METHD_TP_CD_onviewchange();

    }
};

