/**
 * @method
 * @name recvtIsuDel
 * @description 접수 종목을 삭제한다.
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.recvtIsuDel = async function () {
    scwin.TR_JOB = 'D';
    if (! await window.confirm(await $c.stf.getMessageParam('MSG-A006', "신청종목삭제"))) return;
    scwin.vBzProcsNo = await $c.stf.getNewBzProcNo();
    if (scwin.vBzProcsNo.length !== 14) {
        $c.win.alert($c.stf.getMessageParam("MSG-0010", ""));
    } else {
        dma_Isu.set("bzProcsNo", scwin.vBzProcsNo);
        dma_Isu.set("isurCd", txb_isurCd.getValue());

        const reqMap = {
            bzProcsNo: scwin.vBzProcsNo,
            isurCd: txb_isurCd.getValue(),
            acptNo: scwin.gAcptNo,
            byacptnoSeq: scwin.gAcptSeq,
            listBzTpCd: scwin.getListBzTpCd()
        };
        const sbmOptions = {
            id: "sbm_remove",
            action: "/api/listing/lstproc/stock/issuance-manage-applied-isu/remove",
            method: "post",
            isProcessMsg: true
        };
        const res = await $c.sbm.executeDynamic(sbmOptions, reqMap);

        if (res.responseJSON.success) {
            scwin.parentRefresh(); // 목록 다시 조회

            $c.win.alert($c.stf.getMessageParam("MSG-A001", "삭제"));
            await $c.win.closePopup();
        } else {
            $c.win.alert($c.stf.getMessageParam("MSG-A002", "삭제"));
            // $c.stf.alert_error(trs_Save);
        }
    }
};

/**
 * @method
 * @name trs
 * @description 트랜잭션 객체 처리(레거시).
 * @param {Number} trsIdx 번호/개수
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.trs = async function (trsIdx) {
    dma_Isu.set("isurCd", txb_isurCd.getValue());
    dma_Isu.set("listBzTpCd", scwin.getListBzTpCd());
    dma_Isu.set("prefstkTpCd", scwin.getCheckboxNprefStk(chk_PREFSTK_TP_CD, sbx_STKCERT_KIND_CD.getValue()));
    dma_Isu.set("indefinpdYn", chk_INDEFINPD_YN.getValue());
    dma_Isu.set("partctpYn", chk_PARTCTP_YN.getValue());
    dma_Isu.set("acctpYn", chk_ACCTP_YN.getValue());
    dma_Isu.set("ndivtmVoterghtYn", chk_NDIVTM_VOTERGHT_YN.getValue());
    // dma_Isu.set("newstkRelLawstYn", chk_NEWSTK_REL_LAWST_YN.getValue());
    dma_Isu.set("backlistYnBACKLIST_YN", chk_BACKLIST_YN.getValue());
    dma_Isu.set("nparvalstkYn", chk_NPARVALSTK_YN.getValue());

    /*2010.03.05 우회상장 시 우회상장일도 같이 입력 */
    /*2010.07.16 우회상장 시 주식발행코드 입력 */
    if (chk_BACKLIST_YN.getValue() === "Y") {
        dma_BackList.set("isurCd", dma_Isu.get("isurCd"));
        dma_BackList.set("bzProcsNo", dma_Isu.get("bzProcsNo"));
        dma_BackList.set("backlistDd", dma_Isu.get("listDd"));
        dma_BackList.set("backlistDesignYn", "Y");
        dma_BackList.set("stkIsuRsnCd", dma_Isu.get("stkIsuRsnCd"));
    } else {
        dma_BackList.set("isurCd", "");
        dma_BackList.set("bzProcsNo", "");
        dma_BackList.set("backlistDd", "");
        dma_BackList.set("backlistDesignYn", "");
        dma_BackList.set("stkIsuRsnCd", "");
    }

    // 20081017 코스닥이고 발행사유가 이익소각이면 발행일자는 ~ 셋팅된다.
    /* 모델변경으로 제외(not null -> null) 2009.03.31
        if (getObjectValue(sbx_STK_ISU_RSN_CD) == "626"){
            if (dma_Isu.NameString(1, "ISU_DD") == ""){
dma_Isu.setNameString(1, "ISU_DD","~") ;
            }
        }
     */

    dlt_IsuDtl.setBroadcast(false);
    for (i = 0; i <= dlt_IsuDtl.getRowCount(); i++) {
        dlt_IsuDtl.setCellData(i, "bzProcsNo", dma_Isu.get("bzProcsNo"));
        dlt_IsuDtl.setCellData(i, "seq", i);
        // dlt_IsuDtl.NameValue(i, "JOB_TYPE") = TR_JOB_INSERT; //delete 후 insert 한다.

    }
    dlt_IsuDtl.setBroadcast(true, true);
    dlt_PRTDEPO.setBroadcast(false);
    for (i = 0; i <= dlt_PRTDEPO.getRowCount(); i++) {
        dlt_PRTDEPO.setCellData(i, "bzProcsNo", dma_Isu.get("bzProcsNo"));
        dlt_PRTDEPO.setCellData(i, "seq", i); // 저장하기 위해 이벤트를 발생시킨다.
        // dlt_IsuDtl.NameValue(i, "JOB_TYPE") = TR_JOB_INSERT; //delete 후 insert 한다.

    }
    dlt_PRTDEPO.setBroadcast(true, true);
    let vScrenProcTpCd;
    if (scwin.TR_JOB === "I") {
        vScrenProcTpCd = $c.lc.glb.SCREN_PROCS_TP_CD_02;
    } else if (scwin.TR_JOB === "U") {
        vScrenProcTpCd = $c.lc.glb.SCREN_PROCS_TP_CD_03;
    } else if (scwin.TR_JOB === "D") {
        vScrenProcTpCd = $c.lc.glb.SCREN_PROCS_TP_CD_04;
    }

    dma_Base.set("acptNo", scwin.gAcptNo);
    dma_Base.set("byacptnoSeq", scwin.gAcptSeq);
    dma_Base.set("bzProcsNo", scwin.vBzProcsNo);
    dma_Base.set("listMethdTpCd", ibx_LIST_METHD_TP_CD.getValue());
    dma_Base.set("listBzTpCd", scwin.getListBzTpCd());
    dma_Base.set("isurCd", txb_isurCd.getValue());
    dma_Base.set("formCd", scwin.formCd);
    dma_Base.set("stkIsuRsnCd", sbx_STK_ISU_RSN_CD.getValue());
    dma_Base.set("listDd", ibx_LIST_DD.getValue());

    let arr = [
        {
            id: "create"
        },
        {
            id: "modify"
        },
        {
            id: "remove"
        }
    ]
    const sbmOptions = {
        id: "sbm_" + arr[trsIdx - 1].id,
        action: "/api/listing/lstproc/stock/issuance-manage/" + arr[trsIdx - 1].id,
        mediatype: "application/json",
        method: "post",
        ref: 'data:json,[{"id":"dma_Base","key":"baseInfo"},{"id":"dma_Isu","key":"isuInfo"},{"id":"dlt_IsuDtl","key":"dtlInfo"},{"id":"dlt_PRTDEPO","key":"prtdepoInfo"},{"id":"dma_BackList","key":"backlistinfo"}]',
        target: "data:json",
        isProcessMsg: false
    };

    const res = await $c.sbm.executeDynamic(sbmOptions);

    if (res.responseJSON.success) {
        if (res.responseJSON.body.completeYn) {
            scwin.parentRefresh(); // 목록 다시 조회

            if (scwin.TR_JOB === 'D') {
                scwin.alertJobMsg('S');
                await $c.win.closePopup();
            } else {
                await scwin.readSync();

                $c.util.setButtonState("grp_btnBox", "update", scwin.BTN_MAP);

                let msg = "성공적으로 처리되었습니다. \n" + " \n" + " \n" + "시장안내문작성 화면으로 이동하시겠습니까?";
                let result = await $c.win.confirm(msg);
                if (result) {
                    btn_IsuAct.trigger("onclick");
                }
            }
        } else {
            scwin.alertJobMsg('F');
            // $c.stf.alert_error(trs_Save);
        }
    } else {
        scwin.alertJobMsg('F');
        // $c.stf.alert_error(trs_Save);
    }
};

