/**
 * @method
 * @name print
 * @description 화면 내용을 보고서로 출력한다.
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.print = async function () {
    let vReportCd = ica_REPORT_CD.getValue(); // 1^인쇄,2^보호예수인쇄,3^통합인쇄
    let vBzProcsKey = scwin.vBzProcsNo;
    if (vReportCd === "1") {
        let isuRsnCd = sbx_STK_ISU_RSN_CD.getValue();
        if (isuRsnCd === '643') {
            // 상호변경(코)
            scwin.print11(vBzProcsKey);
        } else {
            scwin.print12(vBzProcsKey, 'N');
        }
    } else if (vReportCd === "2") {
        scwin.print2(vBzProcsKey); // 우리기술...

    } else if (vReportCd === "3") {

        const reqMap = {
            isurCd: txb_isurCd.getValue(),
            listDd: ibx_LIST_DD.getValue(),
            stkIsuRsnCd: sbx_STK_ISU_RSN_CD.getValue()
        };
        const sbmOptions = {
            id: "sbm_select",
            action: "/api/listing/lstproc/stock/issuance-manage/print-key/select-list",
            method: "get",
            isProcessMsg: true
        };
        const res = await $c.sbm.executeDynamic(sbmOptions, reqMap);
        if (res.responseJSON.success) {
            let pValue = "";
            let k = 0;
            for (let i = 0; i <= res.responseJSON.body.length; i++) {
                if (k === 0) {
                    pValue = res.responseJSON.body[i].bzProcsNo;
                } else {
                    pValue = pValue + "," + res.responseJSON.body[i].bzProcsNo;
                }
                k++;
            }
            vBzProcsKey = pValue;
            scwin.print12(vBzProcsKey, 'Y');
        }
    }
};

/**
 * @method
 * @name listFee
 * @description 상장수수료를 조회한다.
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.listFee = async function () {
    let reqMap = {
        acptNo: scwin.gAcptNoListFee
    };
    const sbmOptions = {
        id: "sbm_list-fee",
        action: "/api/listing/lstproc/stock/issuance-manage/list-fee",
        method: "get",
        target: "dma_listfee=body",
        isProcessMsg: true
    };
    const res = await $c.sbm.executeDynamic(sbmOptions, reqMap);

    if (res.responseJSON.success) {
        let fee = dma_listfee.get("listCommonSum");
        let feeEx = dma_listfee.get("exmptYn");

        ibx_listFee.setValue(fee);

        if (feeEx === "Y") {
            chk_feeExmpt.setValue(1);
        } else {
            chk_feeExmpt.setValue(0);
        }
    }
};

