 * @method
 * @name setParIsuCd
 * @description 팝업이 돌려준 파라미터 배열을 화면 입력값에 반영한다.
 * @param {Array} arrPar 파라미터 배열
 * @returns {void}
 * @hidden N
 */
scwin.setParIsuCd = function (arrPar) {
    // let dbClickYn =  arrPar[0].DBCLICKYN;
    if (arrPar[0].ISU_CD !== "") {
        ibx_ISU_CD.setValue(arrPar[0].ISU_CD);
        txb_ISU_KOR_NM.setValue(arrPar[0].ISU_KOR_NM);
        ibx_ISU_KOR_ABBRV.setValue(arrPar[0].ISU_KOR_ABBRV);
        ibx_ISU_ENG_NM.setValue(arrPar[0].ISU_ENG_NM);
        ibx_ISU_ENG_ABBRV.setValue(arrPar[0].ISU_ENG_ABBRV);
        ibx_ISU_SRT_CD.setValue(arrPar[0].ISU_SRT_CD);
        ibx_ISU_ENG_SYMBL.setValue(arrPar[0].ISU_ENG_SYMBL);
        sbx_CURR_ISO_CD.setValue(arrPar[0].CURR_ISO_CD);
        if (scwin.vSecugrpID.indexOf($c.lc.glb.SECUGRP_ID_DR) > -1) {
            sbx_STKCERT_KIND_CD.setValue('KDR'); // 주식의종류코드를 셋팅

        } else if (scwin.vSecugrpID.indexOf($c.lc.glb.SECUGRP_ID_FS) > -1) {
            sbx_STKCERT_KIND_CD.setValue('000'); // 주식의종류코드를 셋팅

        } else {
            sbx_STKCERT_KIND_CD.setValue(ibx_ISU_CD.getValue().substring(8, 11)); // 주식의종류코드를 셋팅

        }
        scwin.setPREFSTKEvent();
        scwin.nprefstkReadSync(ibx_ISU_CD.getValue());
        scwin.bfReadSync();
    }
};

