 * @description 우선주(PREFSTK) 여부 변경에 따라 관련 입력 항목 활성화를 처리한다.
 * @returns {void}
 * @hidden N
 */
scwin.setPREFSTKEvent = function () {
    if (scwin.vSecugrpID.indexOf($c.lc.glb.SECUGRP_ID_ST) > -1) {
        if (sbx_STKCERT_KIND_CD.getValue() === '000' || sbx_STKCERT_KIND_CD.getValue().substring(0, 1) === 'K') {
            scwin.setPREFSTKItem(false);
        } else {
            scwin.setPREFSTKItem(true);
        }
    } else {
        scwin.setPREFSTKItem(false);
    }
};

