/**
 * @method
 * @name setCheckboxData
 * @description 체크박스 선택값을 데이터에 반영한다.
 * @param {Object} obj 객체
 * @param {String|Number} val 값
 * @returns {void}
 * @hidden N
 */
scwin.setCheckboxData = function (obj, val) {
    if (val === 'Y') {
        obj.setValue(1);
    } else {
        obj.setValue(0);
    }
};

/**
 * @method
 * @name getCheckboxData
 * @description 데이터 값으로 체크박스 선택 상태를 설정한다.
 * @param {Object} obj 객체
 * @returns {*} 결과 값
 * @hidden N
 */
scwin.getCheckboxData = function (obj) {
    if (obj.checked) {
        return 'Y';
    } else {
        return 'N';
    }
};

/**
 * @method
 * @name setNprefCheckBox
 * @description 신형우선주 체크박스 상태를 설정한다.
 * @param {*} dtsObj dtsObj
 * @returns {void}
 * @hidden N
 */
scwin.setNprefCheckBox = function (dtsObj) {
    scwin.setCheckboxData(chk_INDEFINPD_YN, dtsObj.get("indefinpdYn"));
    scwin.setCheckboxData(chk_PARTCTP_YN, dtsObj.get("partctpYn"));
    scwin.setCheckboxData(chk_ACCTP_YN, dtsObj.get("acctpYn"));
    scwin.setCheckboxData(chk_NDIVTM_VOTERGHT_YN, dtsObj.get("ndivtmVoterghtYn"));
};

/**
 * @method
 * @name checkForm
 * @description 저장 전 입력 폼을 검증한다.
 * @returns {Boolean} 판정 결과
 * @hidden N
 */
scwin.checkForm = function () {
    let vCurDate = $c.date.getServerDateTime();
    if (txb_isurCd.getValue() === "") {
        $c.win.alert("[회사코드] 항목값이  없습니다.");
        txb_isurCd.focus();
        return false;
    }
    if (ibx_LIST_METHD_TP_CD.getValue() === "") {
        $c.win.alert("[상장방식]을 선택하세요.");
        ibx_LIST_METHD_TP_CD.focus();
        return false;
    }
    let vListMthTpCd = ibx_LIST_METHD_TP_CD.getValue();
    if (scwin.vPageTYp === '1') {
        if (vListMthTpCd !== $c.lc.glb.LIST_METHD_TP_CD_2) {
            // $c.win.alert("이화면에서는  상장방식을 [신주상장, 추가상장]만 선택할 수 있습니다.");ibx_LIST_METHD_TP_CD.focus();return false;
            $c.win.alert("이화면에서는  상장방식을 [추가상장]만 선택할 수 있습니다.");
            ibx_LIST_METHD_TP_CD.focus();
            return false;
        }
    } else if (scwin.vPageTYp === '2') {
        if (vListMthTpCd !== $c.lc.glb.LIST_METHD_TP_CD_3) {
            $c.win.alert("이화면에서는  상장방식을 [변경상장]만 선택할 수 있습니다.");
            ibx_LIST_METHD_TP_CD.focus();
            return false;
        }
    }
    if (ibx_ISU_CD.getValue() === "") {
        $c.win.alert("[종목]을 선택하세요.");
        img_ISU_CD.focus();
        return false;
    }
    if (ibx_LIST_METHD_TP_CD.getValue() === $c.lc.glb.LIST_METHD_TP_CD_1) {
        let dbchkCnt = -1;
        dbchkCnt = scwin.checkDoubleListed();
        if (dbchkCnt > 0) {
            $c.win.alert("선택종목은 이미상장된 종목입니다. 확인후 다시 조치바랍니다.");
            return false;
        }
    }
    if (ibx_LIST_METHD_TP_CD.getValue() === $c.lc.glb.LIST_METHD_TP_CD_1) {
        if (ibx_ISU_SRT_CD.getValue() === "") {
            $c.win.alert("[종목단축코드]항목값이  없습니다."); // ibx_ISU_SRT_CD.focus();return false;

        }
        if (txb_ISU_KOR_NM.getValue() === "") {
            $c.win.alert("[한글종목명]을 입력하세요.");
            txb_ISU_KOR_NM.focus();
            return false;
        }
        if (ibx_ISU_KOR_ABBRV.getValue() === "") {
            $c.win.alert("[한글종목약명]을 입력하세요.");
            ibx_ISU_KOR_ABBRV.focus();
            return false;
        }
        if (txb_ISU_ENG_NM.getValue() === "") {
            $c.win.alert("[영문종목명]을 입력하세요.");
            txb_ISU_ENG_NM.focus();
            return false;
        }
        if (ibx_ISU_ENG_ABBRV.getValue() === "") {
            $c.win.alert("[영문종목약명]을 입력하세요.");
            ibx_ISU_ENG_ABBRV.focus();
            return false;
        }
        if (scwin.vSPOT_ISU_TRD_MKT_TP_CD === "1") {
            if (ibx_ISU_ENG_SYMBL.getValue() === "") {
                $c.win.alert("[영문종목심볼]을 입력하세요.");
                ibx_ISU_ENG_SYMBL.focus();
                return false;
            }
            if ($c.lc.engSymblCheck(ibx_ISU_ENG_SYMBL.getValue())) {
                if (!$c.lc.chkCorpSymblDoubleInput(ibx_ISU_ENG_SYMBL.getValue(), txb_isurCd.getValue(), dts_Symbl)) {
                    $c.win.alert(MSG_SYMBL_DOUBLE_INPUT);
                    return false;
                }
            } else {
                ibx_ISU_ENG_SYMBL.focus();
                return false;
            }
        }
    }
    if (ibx_LIST_METHD_TP_CD.getValue() === $c.lc.glb.LIST_METHD_TP_CD_2) {
        // 추가상장
        if (sbx_STK_ISU_RSN_CD.getValue() === "609" || sbx_STK_ISU_RSN_CD.getValue() === "626" || sbx_STK_ISU_RSN_CD.getValue() === "627" ||
            sbx_STK_ISU_RSN_CD.getValue() === "640" || sbx_STK_ISU_RSN_CD.getValue() === "641" || sbx_STK_ISU_RSN_CD.getValue() === "643" ||
            sbx_STK_ISU_RSN_CD.getValue() === "632" || sbx_STK_ISU_RSN_CD.getValue() === "633" || sbx_STK_ISU_RSN_CD.getValue() === "648" ||
            sbx_STK_ISU_RSN_CD.getValue() === "649") {
            $c.win.alert("[추가상장]에 해당하는 주식발행사유가 아닙니다. 주식발행사유를 확인하시기 바랍니다.");
            sbx_STK_ISU_RSN_CD.focus();
            return;
        }
    }
    if (ibx_LIST_METHD_TP_CD.getValue() === $c.lc.glb.LIST_METHD_TP_CD_3) {
        // 변경상장
        if (sbx_STK_ISU_RSN_CD.getValue() === "602" || sbx_STK_ISU_RSN_CD.getValue() === "644" || sbx_STK_ISU_RSN_CD.getValue() === "608" ||
            sbx_STK_ISU_RSN_CD.getValue() === "611" || sbx_STK_ISU_RSN_CD.getValue() === "614" || sbx_STK_ISU_RSN_CD.getValue() === "617" ||
            sbx_STK_ISU_RSN_CD.getValue() === "618" || sbx_STK_ISU_RSN_CD.getValue() === "619" || sbx_STK_ISU_RSN_CD.getValue() === "620" ||
            sbx_STK_ISU_RSN_CD.getValue() === "621" || sbx_STK_ISU_RSN_CD.getValue() === "622" || sbx_STK_ISU_RSN_CD.getValue() === "623" ||
            sbx_STK_ISU_RSN_CD.getValue() === "624" || sbx_STK_ISU_RSN_CD.getValue() === "630" || sbx_STK_ISU_RSN_CD.getValue() === "631" ||
            sbx_STK_ISU_RSN_CD.getValue() === "642") {
