            sbx_STK_ISU_RSN_CD.focus();
            return;
        }
    }

    // 2009.04.07 변경상장일경우는 상장일을 입력안해도 되도록 변경함.
    if (scwin.vPageTYp === '2') {
        // 코스닥 일때만 주식발행사유 600번대
        if (sbx_STK_ISU_RSN_CD.getValue() >= 600 && sbx_STK_ISU_RSN_CD.getValue() !== "625") {
            // 상장일이 없으면 '-' 으로 대체
            if (ibx_LIST_DD.getValue() === "") {
                dma_Isu.setCellData(1, "LIST_DD", '-');
                $c.win.alert("변경상장일 경우 상장일 입력을 안하시면 '-' 으로 처리됩니다.");
            }
        } else {
            if (ibx_LIST_DD.getValue() === "") {
                $c.win.alert("[상장일]을 입력하세요.");
                ibx_LIST_DD.focus();
                return false;
            }
        }
    } else {
        if (ibx_LIST_DD.getValue() === "") {
            $c.win.alert("[상장일]을 입력하세요.");
            ibx_LIST_DD.focus();
            return false;
        }
        if (vCurDate >= ibx_LIST_DD.getValue()) {
            $c.win.alert("[상장일]을 현재일이후로 입력하세요.");
            ibx_LIST_DD.focus();
            return false;
        }
    }
    if (ibx_LIST_METHD_TP_CD.getValue() === $c.lc.glb.LIST_METHD_TP_CD_3) {
        // 20081017 코스닥이고 이익소각이면 발행일자 입력이 필수가 아니도록 변경
        // 20100514 코스닥이고 감자(유상)일 경우 발행일자와 발행회차 입력이 필수가 아니도록 변경
        // 626 : 이익소각, 609 : 감자(유상)
        // 699 : 기타 추가 20100809(강진희)
        // 650:주식소각
        // 625:우선주의 보통주전환  추가(2017.05.15)

        if (sbx_STK_ISU_RSN_CD.getValue() === "626" || sbx_STK_ISU_RSN_CD.getValue() === "609" || sbx_STK_ISU_RSN_CD.getValue() === "650" || sbx_STK_ISU_RSN_CD.getValue() === "625" ||
            sbx_STK_ISU_RSN_CD.getValue() === "699") {

        } else {
            if (ibx_ISU_DD.getValue() === "") {
                $c.win.alert("[발행일]을 입력하세요.");
                ibx_ISU_DD.focus();
                return false;
            }
            if (edt_ISU_RND.getValue() === "") {
                $c.win.alert("[발행회차]를 입력하세요.");
                edt_ISU_RND.focus();
                return false;
            }
        }
        // if ($c.stf.getObjectValue(sbx_STK_ISU_RSN_CD) == "625") {
        //     if (!scwin.checkIsuDtlDtl(dlt_IsuDtl)) return false;
        // }
    }
    if (sbx_STKCERT_KIND_CD.getValue() === "") {
        $c.win.alert("[주식의종류]를 선택하세요.");
        sbx_STKCERT_KIND_CD.focus();
        return false;
    }
    if (sbx_STK_ISU_RSN_CD.getValue() === "") {
        $c.win.alert("[주식발행사유]를 선택하세요.");
        sbx_STK_ISU_RSN_CD.focus();
        return false;
    }
    let isuRsnCd = sbx_STK_ISU_RSN_CD.getValue();
    if (isuRsnCd === '115') {
        $c.win.alert("주식발행사유로 [상장폐지(종목별)]을 선택할수 없습니다.");
        sbx_STK_ISU_RSN_CD.focus();
        return false;
    }
    // 신규상장시 선택하는 발행사유들...
    if (isuRsnCd === '198') {
        $c.win.alert("주식발행사유로 [설립]을 선택할수 없습니다.");
        sbx_STK_ISU_RSN_CD.focus();
        return false;
    }
    if (isuRsnCd === '180') {
        $c.win.alert("주식발행사유로 [회사분할로 인한 재상장]을 선택할수 없습니다.");
        sbx_STK_ISU_RSN_CD.focus();
        return false;
    }
    if (isuRsnCd === '181') {
        $c.win.alert("주식발행사유로 [상장폐지후 신청에 의한 재상장]을 선택할수 없습니다.");
        sbx_STK_ISU_RSN_CD.focus();
        return false;
    }
    if (isuRsnCd === '601') {
        $c.win.alert("주식발행사유로 [신규]를 선택할수 없습니다.");
        sbx_STK_ISU_RSN_CD.focus();
        return false;
    }
    if (isuRsnCd === '643' || isuRsnCd === '160') {
        let dbchkCnt = -1;
        dbchkCnt = scwin.checkComNmInput();
        if (dbchkCnt === 0) {
            $c.win.alert("주식발행사유가 [상호변경]시에는 \r\n\r\n" + "먼저 [변경상장 > 상호변경] 탭화면에서 변경상장일을 동일일자로 상호변경내용을 입력하시기 바랍니다.");
            return false;
        }
        if (ibx_ISU_SHRS.getValue() !== "0") {
            ibx_ISU_SHRS.setValue(0);
            $c.win.alert("주식발행사유가 [상호변경]시에는 [증감" + scwin.visuShrsLabelNm + "수]을 '0'으로 자동설정합니다.");
        }
    }

    ///*
    if (scwin.vSecugrpID.indexOf($c.lc.glb.SECUGRP_ID_MF) < 0 && scwin.vSecugrpID.indexOf($c.lc.glb.SECUGRP_ID_IF) < 0 && scwin.vSecugrpID.indexOf($c.lc.glb.SECUGRP_ID_DR) < 0) {
        if (chk_NPARVALSTK_YN.getValue() !== "Y" && ibx_PARVAL.getValue() === "0") {
            $c.win.alert("[액면가]를 입력하세요.");
            ibx_PARVAL.focus();
            return false;
        }
        if (chk_NPARVALSTK_YN.getValue() === "Y" && ibx_PER1STK_CAP.getValue() === "") {
            $c.win.alert("[주당자본금]을 입력하세요.");
            ibx_PER1STK_CAP.focus();
            return false;
        }
        if (isuRsnCd !== '643' && isuRsnCd !== '160' && // 상호변경
            chk_NPARVALSTK_YN.getValue() !== "Y") {
            // 무액면주식 여부
            if (!scwin.checkZeroNumber(ibx_PARVAL, "액면가")) return false;
        }
    }
    if (isuRsnCd === '640' || isuRsnCd === '170' || // 액면병합
        isuRsnCd === '641' || isuRsnCd === '171') {
        // 액면분할

        let dbchkCnt = -1;
        dbchkCnt = scwin.checkParvalInput();
        if (chk_NPARVALSTK_YN.getValue() !== "Y" && dbchkCnt === 1) {
            $c.win.alert("주식발행사유가 [액면병합, 분할]인데 원부의 액면가와 동일하게 입력하셨습니다.");
            return false;
        }
    } else {
        if (ibx_LIST_METHD_TP_CD.getValue() !== $c.lc.glb.LIST_METHD_TP_CD_1) {
            let dbchkCnt = -1;
            dbchkCnt = scwin.checkParvalInput();
            if (chk_NPARVALSTK_YN.getValue() !== "Y" && dbchkCnt === 0) {
                $c.win.alert("주식발행사유가 [액면병합, 분할] 일때만 액면가를 변경 입력 할 수 있습니다. ");
                return false;
            }
        }
    }

    // if (! fn_checkNumber(ibx_PARVAL, '액면가')) return false;

    if (scwin.vSPOT_ISU_TRD_MKT_TP_CD === '2' && vListMthTpCd !== $c.lc.glb.LIST_METHD_TP_CD_3) {
        // 코스닥이면 변경상장이면 발행가액이 없음, 추가상장일때도 없는경우가 있어 주석처리함 2009.02.03.

        // if (getObjectValue(ibx_ISU_PRC) == "") {

        //	$c.win.alert("[발행가]을 입력하세요.");ibx_ISU_PRC.focus();return false;

        // }

    }
    if (ibx_ISU_SHRS.getValue() === "") {
        $c.win.alert("[증감" + scwin.visuShrsLabelNm + "수]을 입력하세요.");
        ibx_ISU_SHRS.focus();
        return false;
    }

    // 1 신주상장
    // 2 추가상장
