 */
scwin.checkPRTDEPO = function (dtsObj) {
    for (j = 0; j <= dtsObj.getRowCount(); j++) {
        if (dtsObj.getCellData(j, "NM") === "") {
            $c.win.alert("의무보호목록에서 " + j + "행의 성명을 입력하세요.");
