 */
scwin.checkZeroNumber = function (obj, str) {
    if (scwin.vSecugrpID.indexOf($c.lc.glb.SECUGRP_ID_ST) > -1) {
        if (obj.getValue() === 0) {
            $c.win.alert("[" + str + "]를 '" + obj.getValue() + "'으로 입력하셨습니다. 확인 후 재입력바랍니다.");
