 * @returns {*} 결과 값
 * @hidden N
 */
scwin.getListBzTpCd = function () {
    let str = "";
    if (ibx_LIST_METHD_TP_CD.getValue() === $c.lc.glb.LIST_METHD_TP_CD_1) {
        str = $c.lc.glb.LIST_BZ_TP_CD_120; // 신주상장

    } else if (ibx_LIST_METHD_TP_CD.getValue() === $c.lc.glb.LIST_METHD_TP_CD_2) {
        str = $c.lc.glb.LIST_BZ_TP_CD_130; // 추가상장

