 */
scwin.chkPrtdepoCond01 = function () {
    let vRsnCd = sbx_STK_ISU_RSN_CD.getValue();
    if (vRsnCd === '141' || // DR분할
        vRsnCd === '142' || // DR병합
        vRsnCd === '170' || // 액면병합
        vRsnCd === '171' || // 액면분할
        vRsnCd === '172' || // 감자(주식병합)
        vRsnCd === '173' || // 회사분할(존속)
        vRsnCd === '174') {
        // 감자(주식소각)
        return true;
    } else {
        return false;
    }
};

