/**
 * @method
 * @name chkPrtdepoCond03
 * @description 보호예수수정건수가있냐?
 * @returns {Boolean} 판정 결과
 * @hidden N
 */
scwin.chkPrtdepoCond03 = function () {
    // let gPrtdepoCount = dlt_PRTDEPO.CountRow;
    // $c.win.alert("gPrtdepoCount="+gPrtdepoCount);
    let gStat;
    let gStatCnt = 0;
    for (let k = 0; k <= dlt_PRTDEPO.getRowCount(); k++) {
        gStat = dlt_PRTDEPO.getRowStatus(k);
        // if (gStat == TB_JOB_UPDATE) {
        if (gStat === TB_JOB_NORMAL) {
            gStatCnt++;
        }
    }

    // $c.win.alert("gStatCnt="+gStatCnt);
    if (scwin.gPrtdepoCount === gStatCnt) {
        return true;
    } else {
        return false;
    }
};

