/**
 * @method
 * @name isuDtlDtlAdd
 * @description 종목 상세(발행 내역) 행을 추가한다.
 * @returns {void}
 * @hidden N
 */
scwin.isuDtlDtlAdd = function () {
    let isuRnd = ibx_INDVDL_ISU_RND.getValue();
    let isuPrc = ibx_INDVDL_ISU_PRC.getValue();
    let isuShrs = ibx_INDVDL_INCDEC_LIST_SHRS.getValue();
    let isuDd = ibx_INDVDL_ISU_DD.getValue();
    let per1stkCap = ibx_INDVDL_PER1STK_CAP.getValue();
    let corpbndIsuRnd = ibx_CORPBND_ISU_RND.getValue();

    if (isuRnd === "") {
        $c.win.alert("[개별발행회차]를 입력하세요.");
        ibx_INDVDL_ISU_RND.focus();
        return;
    }
    if (isuDd === "") {
        $c.win.alert("[개별발행일]를 입력하세요.");
        ibx_INDVDL_ISU_DD.focus();
        return;
    }
    if (isuPrc === "") {
        // $c.win.alert("[개별발행가]를 입력하세요.");ibx_INDVDL_ISU_PRC.focus();return;

    }
    if (isuShrs === "") {
        $c.win.alert("[개별증감" + scwin.visuShrsLabelNm + "수]를 입력하세요.");
        ibx_INDVDL_INCDEC_LIST_SHRS.focus();
        return;
    }
    let vRow = "";
    if (scwin.vIsuDtlRowPosition !== "") {
        vRow = scwin.vIsuDtlRowPosition;
    } else {
        dlt_IsuDtl.insertRow();
        vRow = dlt_IsuDtl.getRowCount() - 1;
    }

    // $c.win.alert('[ getObjectValue(ibx_INDVDL_ISU_PRC)]'+ getObjectValue(ibx_INDVDL_ISU_PRC));
    // $c.win.alert('[ getObjectValue(ibx_INDVDL_INCDEC_LIST_SHRS)]'+ getObjectValue(ibx_INDVDL_INCDEC_LIST_SHRS));
    dlt_IsuDtl.setCellData(vRow, "isuRnd", isuRnd);
    dlt_IsuDtl.setCellData(vRow, "isuPrc", isuPrc);
    dlt_IsuDtl.setCellData(vRow, "isuShrs", isuShrs);
    dlt_IsuDtl.setCellData(vRow, "isuDd", isuDd);
    dlt_IsuDtl.setCellData(vRow, "per1stkCap", per1stkCap);
    dlt_IsuDtl.setCellData(vRow, "corpbndIsuRnd", corpbndIsuRnd);
    if (dlt_IsuDtl.getCellData(vRow, "per1stkCap") > 0) {
        dlt_IsuDtl.setCellData(vRow, "nparvalstkYn", "Y");
    }
    scwin.isuDtlDtlEvent();
};

/**
