    // dlt_IsuDtl.deleteRow(dlt_IsuDtl.getRowPosition())
    dlt_IsuDtl.removeRows(dlt_IsuDtl.getRowPosition());
    scwin.isuDtlDtlEvent();
};

/**
 * @method
 * @name isuDtlDtlEvent
 * @description 종목 상세(발행 내역) 그리드 변경 이벤트 처리 — 합계·상태를 재계산한다.
 * @returns {void}
 * @hidden N
 */
scwin.isuDtlDtlEvent = function () {
    ibx_INDVDL_ISU_RND.setValue('');
    ibx_INDVDL_ISU_PRC.setValue('');
    ibx_INDVDL_INCDEC_LIST_SHRS.setValue('');
    ibx_INDVDL_ISU_DD.setValue('');
    ibx_INDVDL_PER1STK_CAP.setValue('');
    ibx_CORPBND_ISU_RND.setValue('');
    scwin.isuPrcCalcuate();
    scwin.isuShrsCalcuate();
    scwin.vIsuDtlRowPosition = ""; // 초기화

};

/**
 * @method
 * @name isuPrcCalcuate
 * @description 발행가액을 계산한다.
 * @returns {void}
 * @hidden N
 */
scwin.isuPrcCalcuate = function () {
    let vIsuPrcSum = 0;
    let vIsuRnd = "";
    let vIsuDd = "";
    try {
        if (dlt_IsuDtl.getRowCount() > 0) {
            vIsuPrcSum = Number(dlt_IsuDtl.getCellData(0, "isuPrc"));
            vIsuRnd = dlt_IsuDtl.getCellData(0, "isuRnd");
            vIsuDd = dlt_IsuDtl.getCellData(0, "isuDd");
            if (vIsuRnd === "") {
                vIsuRnd = edt_ISU_RND.getValue();
            }
        }
    } catch (err) {
        $c.win.alert("[개별발행가 계산중  오류]" + err);
    }
    // $c.stf.setObjectValue(ibx_ISU_PRC, vIsuPrcSum);
    edt_ISU_RND.setValue(vIsuRnd);
    ibx_ISU_DD.setValue(vIsuDd);
};

/**
 * @method
 * @name isuShrsCalcuate
 * @description 증감주식수(주) 자동계산
 * @returns {void}
 * @hidden N
 */
scwin.isuShrsCalcuate = function () {
    let vIsuShrsSum = 0;
    try {
        for (i = 0; i <= dlt_IsuDtl.getRowCount(); i++) {
            vIsuShrsSum += Number(dlt_IsuDtl.getCellData(i, "isuShrs"));
        }
    } catch (err) {
        $c.win.alert("[증감" + scwin.visuShrsLabelNm + "수 합산처리 중  오류]" + err);
    }
    ibx_ISU_SHRS.setValue(vIsuShrsSum);
    scwin.calcuAccIsuShrs();    // 변경후 상장주식수(주)
    scwin.calcusuCap();         // 증감 상장자본금
    scwin.calcuAccIsuCap();     // 변경후 상장자본금
};

/**
 * @method
 * @name calcuAccIsuShrs
 * @description 변경후 상장주식수(주) 자동계산
 * @returns {void}
 * @hidden N
 */
scwin.calcuAccIsuShrs = function () {
    try {
        let vsum = Number.parseInt(ibx_BF_ACC_ISU_SHRS.getValue()) + Number.parseInt(ibx_ISU_SHRS.getValue());
        // $c.win.alert( "[vsum]"+vsum);
        ibx_ACC_ISU_SHRS.setValue(vsum);
    } catch (err) {
        $c.win.alert("[변경후 상장증권수 계산 중 오류]" + err);
    }
};

/**
 * @method
 * @name calcusuCap
 * @description 증감 상장자본금 자동계산
 * @returns {void}
 * @hidden N
 */
scwin.calcusuCap = function () {
    if (scwin.vSecugrpID.indexOf($c.lc.glb.SECUGRP_ID_DR) > -1) {
        ibx_ISU_CAP.setValue('');
    } else {
        try {
            let vRsnCd = sbx_STK_ISU_RSN_CD.getValue();
            let vsum = 0;
            if (vRsnCd === '118' || // 이익소각
                vRsnCd === '160' || // 상호변경
                vRsnCd === '170' || // 액면병합
                vRsnCd === '171' || // 액면분할
                vRsnCd === '177') {
                // 주식소각
                vsum = 0; // 유가

            } else if (vRsnCd === '626' || // 이익소각
                vRsnCd === '643' || // 상호변경
                vRsnCd === '640' || // 액면병합
                vRsnCd === '641' || // 액면분할
                vRsnCd === '650') {
                // 주식소각
                vsum = 0; // 코스닥

            } else {
                if (scwin.vSecugrpID.indexOf($c.lc.glb.SECUGRP_ID_MF) > -1 || scwin.vSecugrpID.indexOf($c.lc.glb.SECUGRP_ID_IF) > -1) {
                    // vsum = Number($c.stf.getObjectValue(ibx_ISU_PRC)) * Number($c.stf.getObjectValue(ibx_ISU_SHRS));
                    vsum = Number(dlt_IsuDtl.getCellData(0, "isuPrc")) * Number(ibx_ISU_SHRS.getValue());
                } else {
                    if (chk_NPARVALSTK_YN.getValue() === "Y") {
                        vsum = Number(ibx_PER1STK_CAP.getValue()) * Number(ibx_ISU_SHRS.getValue());
                    } else {
                        vsum = Number(ibx_PARVAL.getValue()) * Number(ibx_ISU_SHRS.getValue());
                    }
                }
            }
            // $c.win.alert( "[증감자본금 vsum]"+vsum);
            ibx_ISU_CAP.setValue(vsum);
        } catch (err) {
            $c.win.alert("[증감 상장자본금 계산 중  오류]" + err);
        }
    }
};

/**
 * @method
 * @name calcuAccIsuCap
 * @description 변경후 상장자본금 자동계산
 * @returns {void}
 * @hidden N
 */
scwin.calcuAccIsuCap = function () {
    if (scwin.vSecugrpID.indexOf($c.lc.glb.SECUGRP_ID_DR) > -1) {
        ibx_ACC_ISU_CAP.setValue('');
    } else {
        try {
            let vRsnCd = sbx_STK_ISU_RSN_CD.getValue();
            let vsum = '';
            if (vRsnCd === '118' || // 이익소각
                vRsnCd === '160' || // 상호변경
                vRsnCd === '170' || // 액면병합
                vRsnCd === '177' || // 주식소각
                vRsnCd === '171') {
                // 액면분할
                vsum = ibx_BF_ACC_ISU_CAP.getValue(); // 유가
                ibx_ISU_CAP.setValue(0); // 유가

            } else if (vRsnCd === '626' || // 이익소각
                vRsnCd === '643' || // 상호변경
                vRsnCd === '640' || // 액면병합
                vRsnCd === '650' || // 주식소각
                vRsnCd === '641') {
                // 액면분할
                vsum = ibx_BF_ACC_ISU_CAP.getValue(); // 코스닥
                ibx_ISU_CAP.setValue(0); // 코스닥

            } else {
                scwin.calcusuCap();
                vsum = Number(ibx_BF_ACC_ISU_CAP.getValue()) + Number(ibx_ISU_CAP.getValue());
            }
            ibx_ACC_ISU_CAP.setValue(vsum);
        } catch (err) {
            $c.win.alert("[변경후 상장자본금 계산 중  오류]" + err);
        }
    }
};

/**
 * @method
 * @name setIsunNmComponent
 * @description 종목명 입력 컴포넌트 표시 상태를 설정한다.
