        txb_ISU_ENG_NM.setReadOnly(false);
        ibx_ISU_ENG_ABBRV.setReadOnly(false);
        ibx_ISU_ENG_SYMBL.setReadOnly(false);
    } else {
        txb_ISU_KOR_NM.setReadOnly(true);
        ibx_ISU_KOR_ABBRV.setReadOnly(true);
        txb_ISU_ENG_NM.setReadOnly(true);
        ibx_ISU_ENG_ABBRV.setReadOnly(true);
        ibx_ISU_ENG_SYMBL.setReadOnly(true);
    }

    if (scwin.vSPOT_ISU_TRD_MKT_TP_CD === '1') {
        grp_KSE.show('');
    } else if (scwin.vSPOT_ISU_TRD_MKT_TP_CD === '2' || scwin.vSPOT_ISU_TRD_MKT_TP_CD === '6') {
        grp_KSE.hide();
    }
};

