/**
 * @method
 * @name print12
 * @description 설명 : 변경상장신청내역 인쇄한다. totalYn : 통합인쇄 여부 배당기산일은 변경전/후를 추가배당일과 동일하게 함-현업요청
 * @param {*} vBzProcsKey vBzProcsKey
 * @param {String} totalYn 여부(Y/N)
 * @returns {Promise<*>} 결과 값
 * @hidden N
 */
scwin.print12 = async function (vBzProcsKey, totalYn) {

    await scwin.reportReadSync(vBzProcsKey, $c.lc.glb.DIV_IDX_ISS_REPORT); // return dts_Print

    dma_Report2.set("isuInfo", dma_Report2.get("comNm") + " / " + dma_Report2.get("repIsuSrtCd"));
    dma_Report2.set("bfCmstkShrs", $c.num.formatNumber(dma_Report2.get("bfCmstkShrs")));
    dma_Report2.set("bf1prefstkShrs", $c.num.formatNumber(dma_Report2.get("bf1prefstkShrs")));
    dma_Report2.set("bf2prefstkShrs", $c.num.formatNumber(dma_Report2.get("bf2prefstkShrs")));
    dma_Report2.set("bf3prefstkShrs", $c.num.formatNumber(dma_Report2.get("bf3prefstkShrs")));
    dma_Report2.set("bfDivReckDd", $c.date.formatDate(dma_Report2.get("bfDivReckDd"), "-"));
    dma_Report2.set("bfIsuCap", $c.num.formatNumber(dma_Report2.get("bfIsuCap")));
    dma_Report2.set("afCmstkShrs", $c.num.formatNumber(dma_Report2.get("afCmstkShrs")));
    dma_Report2.set("af1prefstkShrs", $c.num.formatNumber(dma_Report2.get("af1prefstkShrs")));
    dma_Report2.set("af2prefstkShrs", $c.num.formatNumber(dma_Report2.get("af2prefstkShrs")));
    dma_Report2.set("af3prefstkShrs", $c.num.formatNumber(dma_Report2.get("af3prefstkShrs")));
    dma_Report2.set("afDivReckDd", $c.date.formatDate(dma_Report2.get("afDivReckDd"), "-"));
    dma_Report2.set("afIsuCap", $c.num.formatNumber(dma_Report2.get("afIsuCap")));
    dma_Report2.set("approvDd", $c.date.formatDate(dma_Report2.get("approvDd"), "-"));
    dma_Report2.set("retisecuDd", $c.date.formatDate(dma_Report2.get("retisecuDd")));
    dma_Report2.set("listDd", $c.date.formatDate(dma_Report2.get("retisecuDd"), "-"));

    /* set val, get dts_Report s */
    let gChgCmstkShrs = "";
    let gChg1PrestkShrs = "";
    let gChg2PrestkShrs = "";
    let gChg3PrestkShrs = "";
    let gChgDivDD = "";
    let gChgParVal = "";
    let gChgIsuCap = "";
    let gChgIsuPrc = "";

    // 일단 변경상장을 포함하여 주식발행에서 넣는다.(추가상장인경우 주식발행상세에 데이타 없는경우도 있음)
    gChgCmstkShrs = $c.num.formatNumber(dma_Report2.get("chgCmstkShrs"));
    gChg1PrestkShrs = $c.num.formatNumber(dma_Report2.get("chg1prefstkShrs"));
    gChg2PrestkShrs = $c.num.formatNumber(dma_Report2.get("chg2prefstkShrs"));
    gChg3PrestkShrs = $c.num.formatNumber(dma_Report2.get("chg3prefstkShrs"));
    gChgIsuCap = $c.num.formatNumber(dma_Report2.get("chgIsuCap"));
    gChgIsuPrc = $c.num.formatNumber(dma_Report2.get("chgIsuPrc"));
    gChgDivDD = $c.date.formatDate(dma_Report2.get("chgDivReckDd"), "-");
    gChgParVal = dma_Report2.get("chgParval");
    /* set val, get dts_Report e */

    // 변경상장 s
    if (ibx_LIST_METHD_TP_CD.getValue() !== $c.lc.glb.LIST_METHD_TP_CD_3) {
        await scwin.reportReadSync(vBzProcsKey, $c.lc.glb.DIV_IDX_ISS_DTL_REPORT); // 주식발행상세

        if (dlt_Report4.getRowCount() > 0) {
            // 과거자료는 주식발행상세에 정보가 없어서 주식발행에서 넣는다.
            // 초기화..
            gChgCmstkShrs = "";
            gChg1PrestkShrs = "";
            gChg2PrestkShrs = "";
            gChg3PrestkShrs = "";
            gChgDivDD = "";
            gChgParVal = "";
            gChgIsuCap = "";
            gChgIsuPrc = "";
            for (let i = 0; i <= dlt_Report4.getRowCount(); i++) {
                gChgCmstkShrs += $c.num.formatNumber(dlt_Report4.getCellData(i, "chgCmstkShrs")) + "<br/>";
                gChg1PrestkShrs += $c.num.formatNumber(dlt_Report4.getCellData(i, "chg1prefstkShrs")) + "<br/>";
                gChg2PrestkShrs += $c.num.formatNumber(dlt_Report4.getCellData(i, "chg2prefstkShrs")) + "<br/>";
                gChg3PrestkShrs += $c.num.formatNumber(dlt_Report4.getCellData(i, "chg3prefstkShrs")) + "<br/>";
                gChgIsuCap += $c.num.formatNumber(dlt_Report4.getCellData(i, "chgIsuCap")) + "<br/>";
                gChgIsuPrc += $c.num.formatNumber(dlt_Report4.getCellData(i, "chgIsuPrc")) + "<br/>";
                if (totalYn === 'Y') {
                    gChgDivDD += $c.date.formatDate(dlt_Report4.getCellData(0, "chgDivReckDd"), "-") + "<br/>";
                    gChgParVal += dlt_Report4.getCellData(0, "chgParval") + "<br/>";
                }
            }
            if (totalYn === 'N') {
                gChgDivDD = $c.date.formatDate(dlt_Report4.getCellData(0, "chgDivReckDd"), "-");
                gChgParVal = dlt_Report4.getCellData(0, "chgParval");
            }
        }
    }
    // 변경상장 e

    dma_Report4_1.set("chgCmstkShrs", gChgCmstkShrs);
    dma_Report4_1.set("chg1prefstkShrs", gChg1PrestkShrs);
    dma_Report4_1.set("chg2prefstkShrs", gChg2PrestkShrs);
    dma_Report4_1.set("chg3prefstkShrs", gChg3PrestkShrs);
    dma_Report4_1.set("chgDivReckDd", gChgDivDD);
    dma_Report4_1.set("chgParval", gChgParVal);
    dma_Report4_1.set("chgIsuCap", gChgIsuCap);
    dma_Report4_1.set("chgIsuPrc", gChgIsuPrc);

    await scwin.reportReadSync(vBzProcsKey, $c.lc.glb.DIV_IDX_PRTDEPO_REPORT);

    dma_Report3.setBroadcast(false);
    for (let i = 1; i <= dma_Report3.getRowCount(); i++) {
        dma_Report3.setCellData(i, $c.num.formatNumber(dma_Report3.getCellData(i, "prtdepoShrs")));
    }
    dma_Report3.setBroadcast(true, true);

    // PDF Convert
    let pdf_rptname = "RLDSTF00007";
    let jsonData1 = {"arrayData": []};
    let jsonData2 = {"arrayData": ""};
    jsonData1.arrayData.push(dma_Report4_1.getJSON());
    jsonData2.arrayData = dma_Report3.getAllJSON();
    const userParam = dma_Report2.getJSON();
    userParam.pdf_rptname = pdf_rptname;
    userParam.jsonData1 = jsonData1;
    userParam.jsonData2 = jsonData2;

    // PDF Convert
    const param = {
        url: "/api/listing/common/report/pdf-download",
        reqParam: userParam
    };
    await $c.data.openReportPdf(param);
};

