 * @returns {*} 결과 값
 * @hidden N
 */
scwin.getProvider = function () {
    let url = frame.srcUrl;
    let arr = url.split("?");
    // $c.win.alert(url +"     =      "+ arr);
    // TODO Stage2: 프로젝트 공통 $c.frame 미반입(팝업/프레임 경로) — $c.win.openPopup/getParent 로 재설계
    return (arr.length >= 1 ? $c.frame.path("../" + arr[1]) : undefined);
};

