/**
 * @method
 * @name setPrestkEndDDEvent
 * @description 우선주 존속기간 종료일 변경 이벤트 처리.
 * @returns {void}
 * @hidden N
 */
scwin.setPrestkEndDDEvent = function () {
    if (chk_INDEFINPD_YN.getValue() === "Y") {
        $c.win.alert("이미[무기한여부]가 선택되었습니다.\n\n만료일을 입력하시려면 무기한여부선택을 해제하시고 \n존속기한을 선택하십시요.");
        return;
    }
    if (ibx_PREFSTK_ISU_DD.getValue() === "") {
        $c.win.alert("[우선주발행일]을 입력하세요.");
        ibx_PREFSTK_ISU_DD.focus();
        return;
    }
    let vTgt;
    let vSrc = ibx_PREFSTK_ISU_DD.getValue();
    vTgt = $c.date.addYear(vSrc, ibx_PREFSTK_CONTIN_DEADLINE_YYS.getValue());
    ica_PREFSTK_END_DD.setValue(vTgt);
    vSrc = ica_PREFSTK_END_DD.getValue();
    vTgt = $c.date.addMonth(vSrc.substring(0, 4), vSrc.substring(4, 6), vSrc.substring(6, 8), ibx_PREFSTK_CONTIN_DEADLINE_MM.getValue());
    ica_PREFSTK_END_DD.setValue(vTgt);
    vSrc = ica_PREFSTK_END_DD.getValue();
    vTgt = $c.date.addDate(vSrc, ibx_PREFSTK_CONTIN_DEADLINE_DYS.getValue());
    ica_PREFSTK_END_DD.setValue(vTgt);
};

/**
 * @method
 * @name setNPARVALSTKYNEvent
 * @description 무액면주식 여부 변경 이벤트 처리.
 * @returns {void}
 * @hidden N
 */
scwin.setNPARVALSTKYNEvent = function () {
    if (chk_NPARVALSTK_YN.getValue() === "Y") {
        ibx_PARVAL.setReadOnly(true);
        ibx_PARVAL.ReadOnlyBackColor = '#b9d4f7';
        ibx_PARVAL.setValue('0');
        ibx_PER1STK_CAP.setReadOnly(false);
        ibx_PER1STK_CAP.ReadOnlyBackColor = '#ffffff';
    } else {
        ibx_PARVAL.setReadOnly(false);
        ibx_PARVAL.ReadOnlyBackColor = '#ffffff';
        ibx_PER1STK_CAP.setReadOnly(true);
        ibx_PER1STK_CAP.ReadOnlyBackColor = '#b9d4f7';
        ibx_PER1STK_CAP.setValue('');
    }
};

/**
 * @method
 * @name smsSend
 * @description SMS 발송을 요청한다.
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.smsSend = async function () {
    let vMainFormCd;
    let vListMthTpCd = ibx_LIST_METHD_TP_CD.getValue();
    if (vListMthTpCd === $c.lc.glb.LIST_METHD_TP_CD_3) {
        // 변경상장
        if (scwin.market === "2") {
            vMainFormCd = "70933";
        } else {
            vMainFormCd = "33033";
        }
    } else {
        if (scwin.market === "2") {
            vMainFormCd = "70932";
        } else {
            vMainFormCd = "33032";
        }
    }

    const url = "/lstproc/ULDSTF05014.gfm?ISUR_CD=" + txb_isurCd.getValue() + "&ACPT_NO=" + scwin.gAcptNoListFee + "&FORM_CD=" + vMainFormCd;
    const param = {};

    const options = {
        id: "ULDSTF05014",
        type: "pageFramePopup",
        popupName: "상장수수료발송",
        modal: true,
        width: 410,
        height: 200,
    };

    // await $c.win.openPopup(url, options, param);

    scwin.listFee();
};

