        scwin.reportReadSync(vBzProcsKey, DIV_IDX_ISS_DTL_REPORT); // 주식발행상세

        if (dts_Report.getRowCount() > 0) {
            // 과거자료는 주식발행상세에 정보가 없어서 주식발행에서 넣는다.
