                    gChgParVal += dts_Report.getCellData(1, "CHG_PARVAL") + "\r\n";
                }
            }
            if (totalYn === 'N') {
                gChgDivDD = $c.date.formatDate(dts_Report.getCellData(1, "CHG_DIV_RECK_DD"), "-");
                gChgParVal = dts_Report.getCellData(1, "CHG_PARVAL");
