/**
 * @method
 * @name openIsuPop
 * @description 종목 선택 팝업을 연다.
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.openIsuPop = async function(){
    const data = {
        isurCd: txb_isurCd.getValue(),
        secugrpId: scwin.vSecugrpID,
        keyReturnTyp: "S"

    };
    const opts = {
        id: "ULDSTF92010",
        popupName: "종목선택",
        width: 400,
        height: 250,
        frameModal: "top",
        type: "pageFramePopup",
    };
    let res = await $c.win.openPopup("/ui/lst/common/ULDSTF92010.xml", opts, data);
    if (res) {
        ibx_ISU_CD.setValue(res.isuCd);
        txb_ISU_KOR_NM.setValue(res.isuKorNm);
        ibx_ISU_KOR_ABBRV.setValue(res.isuKorAbbrv);
        txb_ISU_ENG_NM.setValue(res.isuEngNm);
        ibx_ISU_ENG_ABBRV.setValue(res.isuEngAbbrv)
        ibx_ISU_SRT_CD.setValue(res.isuSrtCd);
        ibx_ISU_ENG_SYMBL.setValue(res.isuEngSymbl);
        sbx_CURR_ISO_CD.setValue(res.currIsoCd);

        if (scwin.vSecugrpID.indexOf($c.lc.glb.SECUGRP_ID_DR) > -1) {
            sbx_STKCERT_KIND_CD.setValue('KDR'); // 주식의종류코드를 셋팅

        } else if (scwin.vSecugrpID.indexOf($c.lc.glb.SECUGRP_ID_FS) > -1) {
            sbx_STKCERT_KIND_CD.setValue('000'); // 주식의종류코드를 셋팅

        } else {
            sbx_STKCERT_KIND_CD.setValue(ibx_ISU_CD.getValue().substring(8, 11)); // 주식의종류코드를 셋팅

        }
        scwin.setPREFSTKEvent();
        scwin.nprefstkReadSync(ibx_ISU_CD.getValue());
        scwin.bfReadSync();
    }
}

