 * @method
 * @name openDetailPrtdepo
 * @description 보호예수신규등록시
 * @param {Number} row 행 인덱스
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.openDetailPrtdepo = async function (row) {
    if (row > -1) {
        // 그리드에서 선택시
        scwin.gPrtdepoSeq = row;
    } else {
        // 신규버튼 선택시
        scwin.gPrtdepoSeq = ""; // 초기화
    }

    const opts = {
        id: "ULDSTF92025",
        popupName: "의무보유 등록/수정",
        width: 700,
        height: 750,
        frameModal: "top",
    };

    await $c.win.openPopup("/ui/lst/common/ULDSTF92025.xml", opts, {"bzProcsNo" : dma_Isu.get("bzProcsNo") });
};

/**
 * @method
 * @name ksdStockIssuYn_customFormatter
 * @description ksdStockIssuYn 커스텀 포매터
 * @param {*} data 셀 값(원본 데이터)
 * @param {String} formattedData 표시 형식 문자열
 * @param {Number} rowIndex 행 인덱스
 * @param {Number} columnIndex 열 인덱스
 * @returns {*} 결과 값
 * @hidden N
 */
scwin.ksdStockIssuYn_customFormatter = function (data, formattedData, rowIndex, columnIndex) {
    if(data === "01"){
        return "Y";
    }else if(data === "02"){
        return "N";
    }if(data === "03"){
        return "담당자확인";
    }
};

/**
 * @method
 * @name alertJobMsg
 * @description 처리 결과 안내 — 처리구분(TR_JOB: I/U/D/R/DSCL)에 맞는 작업명으로 성공(S: MSG-A001, S1: MSG-0001)·실패(F: MSG-A002) 메시지를 표시한다.
 * @param {String} gubun 결과 구분 (S | S1 | F)
 * @returns {Promise} $c.win.alert 반환값
 * @hidden N
 * @example scwin.alertJobMsg("S");
 */
scwin.alertJobMsg = function (gubun) {
    const job = (typeof scwin.TR_JOB !== "undefined") ? scwin.TR_JOB : "";
    const jobNm = { I : "저장", U : "수정", D : "삭제", R : "해제", DSCL : "안내문작성" }[job] || "";
    const code = (gubun === "S") ? "MSG-A001" : ((gubun === "S1") ? "MSG-0001" : "MSG-A002");
    return $c.win.alert($c.stf.getMessageParam(code, jobNm));
};
